{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "The COVID-19 pandemic has caused morbidity and mortality, as well as, widespread disruption to people's lives and livelihoods around the world. Given the health and economic threats posed by the pandemic to the global community, there are concerns that rates of suicide and suicidal behaviour may rise during and in its aftermath.",
      "reason": "The abstract background describes the current state of knowledge (pandemic's widespread disruption) and the uncertainty (concerns that suicide rates may rise), addressing the existing knowledge context."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "Our LSR will provide a regular synthesis of the most up-to-date research evidence to guide public health and clinical policy to mitigate the impact of COVID-19 on suicide.",
      "reason": "The need and importance of the review are explained: to provide regular up-to-date synthesis to guide public health and clinical policy during the pandemic."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_10",
      "quote": "Details of the living review method, justification for its use and our transition plan are provided in our protocol (John et al ., 2020a).",
      "reason": "This is the first iteration of a new living systematic review; no prior similar systematic review is identified in the evidence, so the conditional requirement to justify the review relative to existing similar reviews does not apply."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_3",
      "quote": "No studies reported on changes in rates of suicidal behaviour.",
      "reason": "Although the review aims also to assess effectiveness of intervention strategies, the review is not primarily a review of intervention effects; no intervention studies were included, so a mechanism-of-action description is not applicable."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_3",
      "quote": "All articles reported observational data: 12 cross-sectional; eight case series; five modelling; and three service utilisation studies.",
      "reason": "The review is not of complex interventions; all included studies were observational, so a logic model requirement does not apply."
    }
  ],
  "confidence": 82
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "The overarching aim of the review is to identify and appraise any newly published evidence from around the world that assesses the impact of the COVID-19 pandemic on suicide deaths, suicidal behaviours, self-harm and suicidal thoughts, or that assesses the effectiveness of strategies to reduce the risk of suicide deaths, suicidal behaviours, self-harm and suicidal thoughts, resulting from the COVID-19 pandemic.",
      "reason": "The review objectives are explicitly stated in an 'Aim' section, specifying populations/outcomes (suicide deaths, suicidal behaviours, self-harm, suicidal thoughts) and the exposures/interventions of interest, and are further operationalised as explicit research questions in text_8 ('Studies must address one of the following research questions...')."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "PARTIAL",
      "chunk_id": "text_3",
      "quote": "Eligibility criteria include incidence/prevalence of suicidal behaviour, exposure-outcome relationships and effects of interventions in relation to the COVID-19 pandemic.",
      "reason": "Planned comparisons are implied (prevalence during vs not during pandemic, impact of exposures and intervention effects; text_8 lists comparative prevalence/incidence questions), but no formal PICO-formulated statement of planned comparisons for intervention effects is provided."
    }
  ],
  "confidence": 85
}

